```javascript
import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  const cardData = [
    {
      icon: '01',
      title: 'In-House Calibre',
      body: 'Every movement is designed, machined, and finished under one roof.'
    },
    {
      icon: '02',
      title: 'Five-Year Guarantee',
      body: 'Each piece is serviced free of charge for five years from delivery.'
    },
    {
      icon: '03',
      title: 'Hand-Finished Dials',
      body: 'Guilloche cut on a 1912 rose engine, one dial at a time.'
    }
  ];

  const cardWidth = 1.5;
  const cardHeight = 1.9;
  const cardXs = [-1.75, 0, 1.75];

  const materials = [];
  const geometries = [];
  const timelines = [];

  cardData.forEach((data, idx) => {
    const cardGroup = new THREE.Group();
    cardGroup.position.x = cardXs[idx];
    cardGroup.position.y = 0.2;

    // Card plane background
    const planeGeom = new THREE.PlaneGeometry(cardWidth, cardHeight);
    geometries.push(planeGeom);

    const cardTexture = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
    const cardMat = new THREE.MeshStandardMaterial({
      map: cardTexture,
      roughness: 0.6,
      metalness: 0.25,
      clearcoat: 0.15,
      transparent: true,
      opacity: 0
    });
    materials.push(cardMat);

    const plane = new THREE.Mesh(planeGeom, cardMat);
    cardGroup.add(plane);

    // Icon disc
    const discGeom = new THREE.CylinderGeometry(0.2, 0.2, 0.05, 32);
    geometries.push(discGeom);

    const discMat = new THREE.MeshStandardMaterial({
      color: 0x16161d,
      emissive: 0xff2a38,
      emissiveIntensity: 1.6,
      roughness: 0.55,
      metalness: 0.5,
      clearcoat: 0.2,
      transparent: true,
      opacity: 0
    });
    materials.push(discMat);

    const disc = new THREE.Mesh(discGeom, discMat);
    disc.rotation.x = Math.PI / 2;
    disc.position.y = 0.5;
    disc.position.z = 0.05;
    cardGroup.add(disc);

    // Icon text
    try {
      const iconText = ctx.fontAtlas.createText(data.icon, {
        fontSize: 20,
        fontWeight: 700,
        color: 0xff2a38,
        emissive: 0xff2a38,
        emissiveIntensity: 1.6
      });
      iconText.position.copy(disc.position);
      iconText.position.z += 0.05;
      if (iconText.material) {
        iconText.material.transparent = true;
        iconText.material.opacity = 0;
        materials.push(iconText.material);
      }
      cardGroup.add(iconText);
    } catch (e) {}

    // Title text
    try {
      const titleText = ctx.fontAtlas.createText(data.title, {
        fontSize: 20,
        fontWeight: 600,
        color: 0xe8ecf2,
        maxWidth: cardWidth - 0.75
      });
      titleText.position.y = 0.05;
      titleText.position.z = 0.05;
      if (titleText.material) {
        titleText.material.transparent = true;
        titleText.material.opacity = 0;
        materials.push(titleText.material);
      }
      cardGroup.add(titleText);
    } catch (e) {}

    // Body text
    try {
      const bodyText = ctx.fontAtlas.createText(data.body, {
        fontSize: 13,
        fontWeight: 400,
        color: 0x9a9aa8,
        maxWidth: cardWidth - 0.75,
        lineHeight: 1.5
      });
      bodyText.position.y = -0.4;
      bodyText.position.z = 0.05;
      if (bodyText.material) {
        bodyText.material.transparent = true;
        bodyText.material.opacity = 0;
        materials.push(bodyText.material);
      }
      cardGroup.add(bodyText);
    } catch (e) {}

    // Hover handlers
    cardGroup.userData.handlers = {
      onPointerOver: () => {
        const tl = gsap.timeline();
        tl.to(cardGroup.position, {
          y: 0.06,
          z: 0.12,
          duration: 0.18,
          ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
        }, 0);
        tl.to(discMat, {
          emissiveIntensity: 2.2,
          duration: 0.18
        }, 0);
        timelines.push(tl);
      },
      onPointerOut: () => {
        const tl = gsap.timeline();
        tl.to(cardGroup.position, {
          y: 0,
          z: 0,
          duration: 0.18,
          ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
        }, 0);
        tl.to(discMat, {
          emissiveIntensity: 1.6,
          duration: 0.18
        }, 0);
        timelines.push(tl);
      }
    };

    group.add(cardGroup);
  });

  // Stagger mount animation
  const mountTl = gsap.timeline();
  group.children.forEach((card, idx) => {
    mountTl.to(card.position, {
      y: 0,
      duration: 0.5,
      ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
    }, idx * 0.08);

    card.traverse((node) => {
      if (node.isMesh && node.material) {
        mountTl.to(node.material, {
          opacity: 1,
          duration: 0.5,
          ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
        }, idx * 0.08);
      }
    });
  });
  timelines.push(mountTl);

  // Apply scene position
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition.x || 0,
      config.scenePosition.y || 0,
      config.scenePosition.z || 0
    );
    if (config.scenePosition.rotationXYZ) {
      group.rotation.set(
        config.scenePosition.rotationXYZ[0],
        config.scenePosition.rotationXYZ[1],
        config.scenePosition.rotationXYZ[2]
      );
    }
    if (config.scenePosition.scaleXYZ) {
      group.scale.set(
        config.scenePosition.scaleXYZ[0],
        config.scenePosition.scaleXYZ[1],
        config.scenePosition.scaleXYZ[2]
      );
    }
  }

  // Cleanup
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    materials.forEach(mat => mat.dispose());
    geometries.forEach(geom => geom.dispose());
  };

  return group;
}
